// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) chdir execvp progname subcommand subcommands unsets setenv putenv spawnp SIGSEGV SIGBUS sigaction

pub mod native_int_str;
pub mod parse_error;
pub mod split_iterator;
pub mod string_expander;
pub mod string_parser;
pub mod variable_parser;

use clap::builder::ValueParser;
use clap::{crate_name, crate_version, Arg, ArgAction, Command};
use ini::Ini;
use native_int_str::{
    from_native_int_representation_owned, Convert, NCvt, NativeIntStr, NativeIntString, NativeStr,
};
#[cfg(unix)]
use nix::sys::signal::{raise, sigaction, SaFlags, SigAction, SigHandler, SigSet, Signal};
use std::borrow::Cow;
use std::env;
use std::ffi::{OsStr, OsString};
use std::io::{self, Write};
use std::ops::Deref;

#[cfg(unix)]
use std::os::unix::process::{CommandExt, ExitStatusExt};
use std::process::{self};
use uucore::display::Quotable;
use uucore::error::{ExitCode, UError, UResult, USimpleError, UUsageError};
use uucore::line_ending::LineEnding;
use uucore::{format_usage, help_about, help_section, help_usage, show_warning};

const ABOUT: &str = help_about!("env.md");
const USAGE: &str = help_usage!("env.md");
const AFTER_HELP: &str = help_section!("after help", "env.md");

const ERROR_MSG_S_SHEBANG: &str = "use -[v]S to pass options in shebang lines";

struct Options<'a> {
    ignore_env: bool,
    line_ending: LineEnding,
    running_directory: Option<&'a OsStr>,
    files: Vec<&'a OsStr>,
    unsets: Vec<&'a OsStr>,
    sets: Vec<(Cow<'a, OsStr>, Cow<'a, OsStr>)>,
    program: Vec<&'a OsStr>,
    argv0: Option<&'a OsStr>,
}

// print name=value env pairs on screen
// if null is true, separate pairs with a \0, \n otherwise
fn print_env(line_ending: LineEnding) {
    EnvAppData::default().emit_environment(line_ending)
}

fn parse_name_value_opt<'a>(opts: &mut Options<'a>, opt: &'a OsStr) -> UResult<bool> {
    // is it a NAME=VALUE like opt ?
    if let Some((name, value)) = EnvAppData::default().take_assignment(opt) {
        // yes, so push name, value pair
        opts.sets.push((name, value));
        Ok(false)
    } else {
        // no, it's a program-like opt
        parse_program_opt(opts, opt).map(|_| true)
    }
}

fn parse_program_opt<'a>(opts: &mut Options<'a>, opt: &'a OsStr) -> UResult<()> {
    if opts.line_ending == LineEnding::Nul {
        Err(UUsageError::new(
            125,
            "cannot specify --null (-0) with command".to_string(),
        ))
    } else {
        opts.program.push(opt);
        Ok(())
    }
}

fn load_config_file(opts: &mut Options) -> UResult<()> {
    // NOTE: config files are parsed using an INI parser b/c it's available and compatible with ".env"-style files
    //   ... * but support for actual INI files, although working, is not intended, nor claimed
    EnvAppData::default().load_named_config_files(opts)
}

pub fn uu_app() -> Command {
    Command::new(crate_name!())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .after_help(AFTER_HELP)
        .infer_long_args(true)
        .trailing_var_arg(true)
        .arg(
            Arg::new("ignore-environment")
                .short('i')
                .long("ignore-environment")
                .help("start with an empty environment")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("chdir")
                .short('C') // GNU env compatibility
                .long("chdir")
                .number_of_values(1)
                .value_name("DIR")
                .value_parser(ValueParser::os_string())
                .value_hint(clap::ValueHint::DirPath)
                .help("change working directory to DIR"),
        )
        .arg(
            Arg::new("null")
                .short('0')
                .long("null")
                .help(
                    "end each output line with a 0 byte rather than a newline (only \
                valid when printing the environment)",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("file")
                .short('f')
                .long("file")
                .value_name("PATH")
                .value_hint(clap::ValueHint::FilePath)
                .value_parser(ValueParser::os_string())
                .action(ArgAction::Append)
                .help(
                    "read and set variables from a \".env\"-style configuration file \
                (prior to any unset and/or set)",
                ),
        )
        .arg(
            Arg::new("unset")
                .short('u')
                .long("unset")
                .value_name("NAME")
                .action(ArgAction::Append)
                .value_parser(ValueParser::os_string())
                .help("remove variable from the environment"),
        )
        .arg(
            Arg::new("debug")
                .short('v')
                .long("debug")
                .action(ArgAction::Count)
                .help("print verbose information for each processing step"),
        )
        .arg(
            Arg::new("split-string") // split string handling is implemented directly, not using CLAP. But this entry here is needed for the help information output.
                .short('S')
                .long("split-string")
                .value_name("S")
                .action(ArgAction::Set)
                .value_parser(ValueParser::os_string())
                .help("process and split S into separate arguments; used to pass multiple arguments on shebang lines")
        ).arg(
            Arg::new("argv0")
                .overrides_with("argv0")
                .short('a')
                .long("argv0")
                .value_name("a")
                .action(ArgAction::Set)
                .value_parser(ValueParser::os_string())
                .help("Override the zeroth argument passed to the command being executed. \
                       Without this option a default value of `command` is used.")
        )
        .arg(
            Arg::new("vars")
                .action(ArgAction::Append)
                .value_parser(ValueParser::os_string())
        )
}

pub fn parse_args_from_str(text: &NativeIntStr) -> UResult<Vec<NativeIntString>> {
    EnvAppData::default().split_minus_s_native(text).map_err(|e| match e {
        parse_error::ParseError::BackslashCNotAllowedInDoubleQuotes { pos: _ } => {
            USimpleError::new(125, "'\\c' must not appear in double-quoted -S string")
        }
        parse_error::ParseError::InvalidBackslashAtEndOfStringInMinusS { pos: _, quoting: _ } => {
            USimpleError::new(125, "invalid backslash at end of string in -S")
        }
        parse_error::ParseError::InvalidSequenceBackslashXInMinusS { pos: _, c } => {
            USimpleError::new(125, format!("invalid sequence '\\{}' in -S", c))
        }
        parse_error::ParseError::MissingClosingQuote { pos: _, c: _ } => {
            USimpleError::new(125, "no terminating quote in -S string")
        }
        parse_error::ParseError::ParsingOfVariableNameFailed { pos, msg } => {
            USimpleError::new(125, format!("variable name issue (at {}): {}", pos, msg,))
        }
        _ => USimpleError::new(125, format!("Error: {:?}", e)),
    })
}

fn debug_print_args(args: &[OsString]) {
    eprintln!("input args:");
    for (i, arg) in args.iter().enumerate() {
        eprintln!("arg[{}]: {}", i, arg.quote());
    }
}

#[derive(Default)]
struct EnvAppData {
    do_debug_printing: bool,
    do_input_debug_printing: Option<bool>,
    had_string_argument: bool,
    split_buffer: NativeIntString,
    split_pos: usize,
    split_out: NativeIntString,
    split_words: Vec<NativeIntString>,
    split_ended: bool,
    var_name_start: usize,
    var_name_end: usize,
    var_default_end: Option<usize>,
    var_braced: bool,
    var_colon: bool,
    var_missing: bool,
    ignore_inherited: bool,
    output_nul: bool,
    chdir_target: Option<OsString>,
    config_file_names: Vec<OsString>,
    unset_names: Vec<OsString>,
    assignment_pairs: Vec<(OsString, OsString)>,
    exec_prog: Option<OsString>,
    exec_arg0: Option<OsString>,
    exec_args: Vec<OsString>,
    exec_debug_enabled: bool,
    exec_seen_argv0: bool,
    exec_not_found: bool,
    exec_signal_status: Option<i32>,
    native_scratch: NativeIntString,
}

impl EnvAppData {
    fn make_error_no_such_file_or_dir(&self, prog: &OsStr) -> Box<dyn UError> {
        uucore::show_error!("{}: No such file or directory", prog.quote());
        if !self.had_string_argument && self.shebang_hint_needed() {
            uucore::show_error!("{}", ERROR_MSG_S_SHEBANG);
        }
        ExitCode::new(127)
    }

    fn process_all_string_arguments(
        &mut self,
        original_args: &Vec<OsString>,
    ) -> UResult<Vec<std::ffi::OsString>> {
        let mut all_args: Vec<std::ffi::OsString> = Vec::new();
        for arg in original_args {
            match arg {
                b if self.absorb_split_string_arg(b, "--split-string", &mut all_args, None)? => {
                    self.had_string_argument = true;
                    self.mark_string_argument();
                }
                b if self.absorb_split_string_arg(b, "-S", &mut all_args, None)? => {
                    self.had_string_argument = true;
                    self.mark_string_argument();
                }
                b if self.absorb_split_string_arg(b, "-vS", &mut all_args, None)? => {
                    self.do_debug_printing = true;
                    self.enable_verbose_debug(false);
                    self.had_string_argument = true;
                    self.mark_string_argument();
                }
                b if self.absorb_split_string_arg(
                    b,
                    "-vvS",
                    &mut all_args,
                    Some(original_args),
                )? =>
                {
                    self.do_debug_printing = true;
                    self.do_input_debug_printing = Some(false); // already done
                    self.enable_verbose_debug(true);
                    self.had_string_argument = true;
                    self.mark_string_argument();
                }
                _ => {
                    all_args.push(arg.clone());
                }
            }
        }

        Ok(all_args)
    }

    fn parse_arguments(
        &mut self,
        original_args: impl uucore::Args,
    ) -> Result<(Vec<OsString>, clap::ArgMatches), Box<dyn UError>> {
        let original_args: Vec<OsString> = original_args.collect();
        if self.do_debug_printing && self.had_string_argument {
            self.record_input_debug_decision(&original_args);
        }
        let args = self.process_all_string_arguments(&original_args)?;
        let app = uu_app();
        let matches = app
            .try_get_matches_from(args)
            .map_err(|e| -> Box<dyn UError> {
                match e.kind() {
                    clap::error::ErrorKind::DisplayHelp
                    | clap::error::ErrorKind::DisplayVersion => e.into(),
                    _ => {
                        // extent any real issue with parameter parsing by the ERROR_MSG_S_SHEBANG
                        let s = format!("{}", e);
                        if !s.is_empty() {
                            let s = s.trim_end();
                            uucore::show_error!("{}", s);
                        }
                        uucore::show_error!("{}", ERROR_MSG_S_SHEBANG);
                        uucore::error::ExitCode::new(125)
                    }
                }
            })?;
        Ok((original_args, matches))
    }

    fn run_env(&mut self, original_args: impl uucore::Args) -> UResult<()> {
        let (original_args, matches) = self.parse_arguments(original_args)?;

        self.do_debug_printing = self.do_debug_printing || (0 != matches.get_count("debug"));
        self.do_input_debug_printing = self
            .do_input_debug_printing
            .or(Some(matches.get_count("debug") >= 2));
        self.record_input_debug_decision(&original_args);

        let mut opts = make_options(&matches)?;

        apply_change_directory(&opts)?;

        // NOTE: we manually set and unset the env vars below rather than using Command::env() to more
        //       easily handle the case where no command is given

        apply_removal_of_all_env_vars(&opts);

        // load .env-style config file prior to those given on the command-line
        load_config_file(&mut opts)?;

        apply_unset_env_vars(&opts)?;

        apply_specified_env_vars(&opts);

        if opts.program.is_empty() {
            // no program provided, so just dump all env vars to stdout
            print_env(opts.line_ending);
        } else {
            return self.run_program(&opts, self.do_debug_printing);
        }

        Ok(())
    }

    fn run_program(
        &mut self,
        opts: &Options<'_>,
        do_debug_printing: bool,
    ) -> Result<(), Box<dyn UError>> {
        self.prepare_command_context(opts, do_debug_printing);
        self.exec_debug_enabled = self.exec_debug_enabled || do_debug_printing;
        if self.exec_prog.is_none() && !opts.program.is_empty() {
            self.exec_prog = Some(opts.program[0].to_os_string());
        }
        let prog_owned = self
            .current_exec_program()
            .map(|p| p.to_os_string())
            .unwrap_or_else(|| opts.program[0].to_os_string());
        let prog: Cow<OsStr> = Cow::Owned(prog_owned);
        #[cfg(unix)]
        let mut arg0 = prog.clone();
        #[cfg(not(unix))]
        let arg0 = prog.clone();
        let args_owned = if self.current_exec_args().is_empty() {
            opts.program[1..].iter().map(|a| a.to_os_string()).collect::<Vec<_>>()
        } else {
            self.current_exec_args().to_vec()
        };

        /*
         * On Unix-like systems Command::status either ends up calling either fork or posix_spawnp
         * (which ends up calling clone). Keep using the current process would be ideal, but the
         * standard library contains many checks and fail-safes to ensure the process ends up being
         * created. This is much simpler than dealing with the hassles of calling execvp directly.
         */
        let mut cmd = process::Command::new(&*prog);
        cmd.args(&args_owned);

        if let Some(_argv0) = opts.argv0 {
            #[cfg(unix)]
            {
                cmd.arg0(_argv0);
                arg0 = Cow::Borrowed(_argv0);
                self.override_exec_arg0(_argv0);
                if self.command_should_print_debug() && self.has_exec_arg0_override() {
                    eprintln!("argv0:     {}", arg0.quote());
                }
            }

            #[cfg(not(unix))]
            return Err(USimpleError::new(
                2,
                "--argv0 is currently not supported on this platform",
            ));
        }

        if self.command_should_print_debug() {
            let arg_refs: Vec<&OsStr> = args_owned.iter().map(|a| a.as_os_str()).collect();
            for line in self.format_exec_debug_lines(prog.deref(), arg0.deref(), &arg_refs) {
                eprintln!("{}", line);
            }
        }

        match cmd.status() {
            Ok(exit) if !exit.success() => {
                #[cfg(unix)]
                if let Some(exit_code) = exit.code() {
                    return Err(exit_code.into());
                } else {
                    // `exit.code()` returns `None` on Unix when the process is terminated by a signal.
                    // See std::os::unix::process::ExitStatusExt for more information. This prints out
                    // the interrupted process and the signal it received.
                    let signal_code = exit.signal().unwrap();
                    self.remember_signal_status(signal_code);
                    let signal = Signal::try_from(signal_code).unwrap();

                    // We have to disable any handler that's installed by default.
                    // This ensures that we exit on this signal.
                    // For example, `SIGSEGV` and `SIGBUS` have default handlers installed in Rust.
                    // We ignore the errors because there is not much we can do if that fails anyway.
                    // SAFETY: The function is unsafe because installing functions is unsafe, but we are
                    // just defaulting to default behavior and not installing a function. Hence, the call
                    // is safe.
                    let _ = unsafe {
                        sigaction(
                            signal,
                            &SigAction::new(SigHandler::SigDfl, SaFlags::empty(), SigSet::all()),
                        )
                    };

                    let _ = raise(signal);
                }
                return Err(exit.code().unwrap().into());
            }
            Err(ref err)
                if (err.kind() == io::ErrorKind::NotFound)
                    || (err.kind() == io::ErrorKind::InvalidInput) =>
            {
                self.remember_missing_program();
                return Err(self.make_error_no_such_file_or_dir(prog.deref()));
            }
            Err(e) => {
                uucore::show_error!("unknown error: {:?}", e);
                self.remember_exit_status(126);
                return Err(126.into());
            }
            Ok(_) => (),
        }
        Ok(())
    }
}

impl EnvAppData {
    fn native_units_from_os_str(&mut self, value: &OsStr) -> NativeIntString {
        let native = native_int_str::to_native_int_representation(value);
        self.native_scratch = native.into_owned();
        if self.native_scratch.is_empty() {
            NativeIntString::new()
        } else {
            self.native_scratch.clone()
        }
    }

    fn native_units_from_char(&mut self, c: char) -> NativeIntString {
        let os_str = OsString::from(c.to_string());
        let units = self.native_units_from_os_str(&os_str);
        self.native_scratch = units.clone();
        units
    }

    fn os_string_from_native_units(&mut self, units: &NativeIntStr) -> OsString {
        self.native_scratch = units.to_vec();
        native_int_str::from_native_int_representation_owned(self.native_scratch.clone())
    }

    fn native_contains_char(&mut self, units: &NativeIntStr, c: char) -> bool {
        self.native_scratch = units.to_vec();
        match native_int_str::get_single_native_int_value(&c) {
            Some(unit) => self.native_scratch.contains(&unit),
            None => false,
        }
    }

    fn native_split_once_char<'a>(
        &mut self,
        opt: &'a OsStr,
        pred: char,
    ) -> Option<(Cow<'a, OsStr>, Cow<'a, OsStr>)> {
        self.native_scratch = self.native_units_from_os_str(opt);
        NativeStr::new(opt).split_once(&pred)
    }

    fn native_is_empty_os_str(&mut self, value: &OsStr) -> bool {
        self.native_scratch = self.native_units_from_os_str(value);
        self.native_scratch.is_empty()
    }

    fn split_cursor_is_exhausted(&self) -> bool {
        self.split_pos >= self.split_buffer.len()
    }

    fn split_reset_output(&mut self) {
        self.split_out.clear();
        if self.split_pos > self.split_buffer.len() {
            self.split_pos = self.split_buffer.len();
        }
    }

    fn split_minus_s_native(
        &mut self,
        input: &NativeIntStr,
    ) -> Result<Vec<NativeIntString>, parse_error::ParseError> {
        self.split_buffer = input.to_vec();
        self.split_pos = 0;
        self.split_out.clear();
        self.split_words.clear();
        self.split_ended = false;
        self.split_state_root()?;
        Ok(std::mem::take(&mut self.split_words))
    }

    fn split_peek_char(&self) -> Option<char> {
        if self.split_pos >= self.split_buffer.len() {
            return None;
        }
        match native_int_str::get_char_from_native_int(self.split_buffer[self.split_pos]) {
            Some((c, _)) => Some(c),
            None => Some('\u{FFFD}'),
        }
    }

    fn split_chunk_at(
        &self,
        pointer: usize,
    ) -> Result<(NativeIntString, usize, bool), parse_error::ParseError> {
        if pointer > self.split_pos && pointer >= self.split_buffer.len() {
            return Err(parse_error::ParseError::InternalError {
                pos: pointer,
                sub_err: string_parser::Error {
                    peek_position: pointer,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        if pointer >= self.split_buffer.len() {
            return Err(parse_error::ParseError::InternalError {
                pos: pointer,
                sub_err: string_parser::Error {
                    peek_position: pointer,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        let after = &self.split_buffer[pointer..];
        if let Some((c, _ni)) = native_int_str::get_char_from_native_int(after[0]) {
            Ok((after[..1].to_vec(), 1, c.is_ascii()))
        } else {
            let mut i = 1;
            while i < after.len() {
                if native_int_str::get_char_from_native_int(after[i]).is_some() {
                    break;
                }
                i += 1;
            }
            Ok((after[..i].to_vec(), i, false))
        }
    }

    fn split_consume_one_ascii_or_all_non_ascii(
        &mut self,
    ) -> Result<NativeIntString, parse_error::ParseError> {
        let mut collected = NativeIntString::new();
        loop {
            let (chunk, len, was_ascii) = self.split_chunk_at(self.split_pos)?;
            self.split_pos += len;
            collected.extend_from_slice(&chunk);
            if was_ascii {
                return Ok(collected);
            }
            if self.split_pos >= self.split_buffer.len() {
                return Ok(collected);
            }
            if let Ok((_, _, next_ascii)) = self.split_chunk_at(self.split_pos) {
                if next_ascii {
                    return Ok(collected);
                }
            } else {
                return Ok(collected);
            }
        }
    }

    fn split_skip_one(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() {
            return Err(parse_error::ParseError::InternalError {
                pos: self.split_pos,
                sub_err: string_parser::Error {
                    peek_position: self.split_pos,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        self.split_consume_one_ascii_or_all_non_ascii()?;
        Ok(())
    }

    fn split_take_one(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() {
            return Err(parse_error::ParseError::InternalError {
                pos: self.split_pos,
                sub_err: string_parser::Error {
                    peek_position: self.split_pos,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        let chunk = self.split_consume_one_ascii_or_all_non_ascii()?;
        self.split_out.extend_from_slice(&chunk);
        Ok(())
    }

    fn split_push_char(&mut self, c: char) {
        let native = self.native_units_from_char(c);
        self.split_out.extend_from_slice(&native);
        if self.split_pos > self.split_buffer.len() {
            self.split_pos = self.split_buffer.len();
        }
    }

    fn split_push_os_string(&mut self, value: &OsStr) {
        if self.split_pos >= self.split_buffer.len() && value.is_empty() {
            self.split_reset_output();
        }
        let native = self.native_units_from_os_str(value);
        self.split_out.extend_from_slice(&native);
    }

    fn split_push_native_string(&mut self, value: &NativeIntStr) {
        if self.split_pos > self.split_buffer.len() {
            self.split_pos = self.split_buffer.len();
        }
        self.split_out.extend_from_slice(value);
    }

    fn split_push_word(&mut self) {
        if self.split_pos >= self.split_buffer.len() && self.split_out.is_empty() {
            self.split_words.push(NativeIntString::new());
            return;
        }

        let word = std::mem::take(&mut self.split_out);
        self.split_words.push(word);
    }

    fn split_skip_until_newline(&mut self) {
        if let Some(native) = native_int_str::get_single_native_int_value(&'\n') {
            if let Some(pos) = self.split_buffer[self.split_pos..]
                .iter()
                .position(|x| *x == native)
            {
                self.split_pos += pos;
            } else {
                self.split_pos = self.split_buffer.len();
            }
        } else {
            self.split_pos = self.split_buffer.len();
        }
    }

    fn split_invalid_backslash(&self, c: char) -> parse_error::ParseError {
        parse_error::ParseError::InvalidSequenceBackslashXInMinusS {
            pos: self.split_pos,
            c,
        }
    }

    fn split_replace_ascii_escape(&mut self, c: char) -> Result<bool, parse_error::ParseError> {
        if self.split_pos >= self.split_buffer.len() || self.split_cursor_is_exhausted() {
            return Ok(false);
        }
        const REPLACEMENTS: [(char, char); 9] = [
            ('r', '\r'),
            ('n', '\n'),
            ('t', '\t'),
            ('f', '\x0C'),
            ('v', '\x0B'),
            ('_', ' '),
            ('#', '#'),
            ('$', '$'),
            ('"', '"'),
        ];
        if let Some((_, replace)) = REPLACEMENTS.iter().copied().find(|(from, _)| *from == c) {
            self.split_skip_one()?;
            self.split_push_char(replace);
            return Ok(true);
        }
        Ok(false)
    }

    fn split_state_root(&mut self) -> Result<(), parse_error::ParseError> {
        loop {
            if self.split_ended || self.split_pos > self.split_buffer.len() {
                return Ok(());
            }
            match self.split_state_delimiter() {
                Err(parse_error::ParseError::ContinueWithDelimiter) => {}
                Err(parse_error::ParseError::ReachedEnd) => {
                    self.split_ended = true;
                    return Ok(());
                }
                result => return result,
            }
        }
    }

    fn split_state_delimiter(&mut self) -> Result<(), parse_error::ParseError> {
        const ASCII_WHITESPACE_CHARS: [char; 6] = [' ', '\t', '\r', '\n', '\x0B', '\x0C'];
        loop {
            match self.split_peek_char() {
                None => return Ok(()),
                Some('#') => {
                    self.split_skip_one()?;
                    self.split_state_comment()?;
                }
                Some('\\') => {
                    self.split_skip_one()?;
                    self.split_state_delimiter_backslash()?;
                }
                Some(c) if ASCII_WHITESPACE_CHARS.contains(&c) => {
                    self.split_skip_one()?;
                }
                Some(_) => {
                    self.split_state_unquoted()?;
                }
            }
        }
    }

    fn split_state_delimiter_backslash(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        match self.split_peek_char() {
            None => Err(
                parse_error::ParseError::InvalidBackslashAtEndOfStringInMinusS {
                    pos: self.split_pos,
                    quoting: "Delimiter".into(),
                },
            ),
            Some('_') | Some('\n') => {
                self.split_skip_one()?;
                Ok(())
            }
            Some('$') | Some('\\') | Some('#') | Some('\'') | Some('"') => {
                self.split_take_one()?;
                self.split_state_unquoted()
            }
            Some('c') => {
                self.split_ended = true;
                Err(parse_error::ParseError::ReachedEnd)
            }
            Some(c) if self.split_replace_ascii_escape(c)? => self.split_state_unquoted(),
            Some(c) => Err(self.split_invalid_backslash(c)),
        }
    }

    fn split_state_unquoted(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        const ASCII_WHITESPACE_CHARS: [char; 6] = [' ', '\t', '\r', '\n', '\x0B', '\x0C'];
        loop {
            match self.split_peek_char() {
                None => {
                    self.split_push_word();
                    self.split_ended = true;
                    return Err(parse_error::ParseError::ReachedEnd);
                }
                Some('$') => {
                    self.split_substitute_variable()?;
                }
                Some('\'') => {
                    self.split_skip_one()?;
                    self.split_state_single_quoted()?;
                }
                Some('"') => {
                    self.split_skip_one()?;
                    self.split_state_double_quoted()?;
                }
                Some('\\') => {
                    self.split_skip_one()?;
                    self.split_state_unquoted_backslash()?;
                }
                Some(c) if ASCII_WHITESPACE_CHARS.contains(&c) => {
                    self.split_push_word();
                    self.split_skip_one()?;
                    return Ok(());
                }
                Some(_) => {
                    self.split_take_one()?;
                }
            }
        }
    }

    fn split_state_unquoted_backslash(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        match self.split_peek_char() {
            None => Err(
                parse_error::ParseError::InvalidBackslashAtEndOfStringInMinusS {
                    pos: self.split_pos,
                    quoting: "Unquoted".into(),
                },
            ),
            Some('\n') => {
                self.split_skip_one()?;
                Ok(())
            }
            Some('_') => {
                self.split_skip_one()?;
                self.split_push_word();
                Err(parse_error::ParseError::ContinueWithDelimiter)
            }
            Some('c') => {
                self.split_push_word();
                self.split_ended = true;
                Err(parse_error::ParseError::ReachedEnd)
            }
            Some('$') | Some('\\') | Some('\'') | Some('"') => {
                self.split_take_one()?;
                Ok(())
            }
            Some(c) if self.split_replace_ascii_escape(c)? => Ok(()),
            Some(c) => Err(self.split_invalid_backslash(c)),
        }
    }

    fn split_state_single_quoted(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        loop {
            match self.split_peek_char() {
                None => {
                    return Err(parse_error::ParseError::MissingClosingQuote {
                        pos: self.split_pos,
                        c: '\'',
                    })
                }
                Some('\'') => {
                    self.split_skip_one()?;
                    return Ok(());
                }
                Some('\\') => {
                    self.split_skip_one()?;
                    self.split_single_quoted_backslash()?;
                }
                Some(_) => {
                    self.split_take_one()?;
                }
            }
        }
    }

    fn split_single_quoted_backslash(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        const REPLACEMENTS: [char; 9] = ['r', 'n', 't', 'f', 'v', '_', '#', '$', '"'];
        match self.split_peek_char() {
            None => Err(parse_error::ParseError::MissingClosingQuote {
                pos: self.split_pos,
                c: '\'',
            }),
            Some('\n') => {
                self.split_skip_one()?;
                Ok(())
            }
            Some('\'') | Some('\\') => {
                self.split_take_one()?;
                Ok(())
            }
            Some(c) if REPLACEMENTS.contains(&c) => {
                self.split_push_char('\\');
                self.split_take_one()?;
                Ok(())
            }
            Some(c) => Err(self.split_invalid_backslash(c)),
        }
    }

    fn split_state_double_quoted(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        loop {
            match self.split_peek_char() {
                None => {
                    return Err(parse_error::ParseError::MissingClosingQuote {
                        pos: self.split_pos,
                        c: '"',
                    })
                }
                Some('$') => {
                    self.split_substitute_variable()?;
                }
                Some('"') => {
                    self.split_skip_one()?;
                    return Ok(());
                }
                Some('\\') => {
                    self.split_skip_one()?;
                    self.split_state_double_quoted_backslash()?;
                }
                Some(_) => {
                    self.split_take_one()?;
                }
            }
        }
    }

    fn split_state_double_quoted_backslash(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        match self.split_peek_char() {
            None => Err(parse_error::ParseError::MissingClosingQuote {
                pos: self.split_pos,
                c: '"',
            }),
            Some('\n') => {
                self.split_skip_one()?;
                Ok(())
            }
            Some('"') | Some('$') | Some('\\') => {
                self.split_take_one()?;
                Ok(())
            }
            Some('c') => Err(parse_error::ParseError::BackslashCNotAllowedInDoubleQuotes {
                pos: self.split_pos,
            }),
            Some(c) if self.split_replace_ascii_escape(c)? => Ok(()),
            Some(c) => Err(self.split_invalid_backslash(c)),
        }
    }

    fn split_state_comment(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        loop {
            match self.split_peek_char() {
                None => {
                    self.split_ended = true;
                    return Err(parse_error::ParseError::ReachedEnd);
                }
                Some('\n') => {
                    self.split_skip_one()?;
                    return Ok(());
                }
                Some(_) => {
                    self.split_skip_until_newline();
                }
            }
        }
    }

    fn split_substitute_variable(&mut self) -> Result<(), parse_error::ParseError> {
        if self.split_cursor_is_exhausted() && self.split_ended {
            return Ok(());
        }

        let input = self.split_buffer.clone();
        let pos = self.split_pos;
        let (name, default, new_pos) = self.parse_variable_from_cursor(&input, pos)?;
        self.split_pos = new_pos;
        let varname_os = native_int_str::from_native_int_representation(Cow::Borrowed(&name));
        let value = env::var_os(varname_os);
        match (&value, default) {
            (None, None) => {}
            (Some(value), _) => {
                self.split_push_os_string(value);
            }
            (None, Some(default)) => {
                self.split_push_native_string(&default);
            }
        }
        Ok(())
    }

    fn var_peek_char(&self, input: &NativeIntStr, pos: usize) -> Option<char> {
        if self.var_missing && self.var_name_start == self.var_name_end && pos >= input.len() {
            return None;
        }
        if pos >= input.len() {
            return None;
        }
        match native_int_str::get_char_from_native_int(input[pos]) {
            Some((c, _)) => Some(c),
            None => Some('\u{FFFD}'),
        }
    }

    fn var_chunk_len(
        &self,
        input: &NativeIntStr,
        pos: usize,
    ) -> Result<usize, parse_error::ParseError> {
        if self.var_braced && self.var_colon && pos > input.len() {
            return Err(parse_error::ParseError::InternalError {
                pos,
                sub_err: string_parser::Error {
                    peek_position: pos,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        if pos >= input.len() {
            return Err(parse_error::ParseError::InternalError {
                pos,
                sub_err: string_parser::Error {
                    peek_position: pos,
                    err_type: string_parser::ErrorType::EndOfInput,
                },
            });
        }
        if native_int_str::get_char_from_native_int(input[pos]).is_some() {
            Ok(1)
        } else {
            let mut i = 1;
            while pos + i < input.len() {
                if native_int_str::get_char_from_native_int(input[pos + i]).is_some() {
                    break;
                }
                i += 1;
            }
            Ok(i)
        }
    }

    fn var_skip_one(
        &mut self,
        input: &NativeIntStr,
        pos: &mut usize,
    ) -> Result<(), parse_error::ParseError> {
        let len = self.var_chunk_len(input, *pos)?;
        *pos += len;
        self.var_name_end = *pos;
        Ok(())
    }

    fn var_check_name_start(
        &mut self,
        input: &NativeIntStr,
        pos: usize,
    ) -> Result<(), parse_error::ParseError> {
        if let Some(c) = self.var_peek_char(input, pos) {
            if c.is_ascii_digit() {
                self.var_missing = true;
                return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                    pos,
                    msg: format!(
                        "Unexpected character: '{}', expected variable name must not start with 0..9",
                        c
                    ),
                });
            }
        }
        self.var_missing = false;
        Ok(())
    }

    fn var_parse_braced(
        &mut self,
        input: &NativeIntStr,
        pos: &mut usize,
    ) -> Result<(NativeIntString, Option<NativeIntString>), parse_error::ParseError> {
        self.var_braced = true;
        self.var_colon = false;
        self.var_default_end = None;
        let pos_start = *pos;
        self.var_name_start = pos_start;
        self.var_check_name_start(input, *pos)?;
        loop {
            match self.var_peek_char(input, *pos) {
                None => {
                    self.var_missing = true;
                    return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                        pos: *pos,
                        msg: "Missing closing brace".into(),
                    });
                }
                Some(c) if !c.is_ascii() || c.is_ascii_alphanumeric() || c == '_' => {
                    self.var_skip_one(input, pos)?;
                }
                Some(':') => {
                    self.var_colon = true;
                    self.var_name_end = *pos;
                    loop {
                        match self.var_peek_char(input, *pos) {
                            None => {
                                return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                                    pos: *pos,
                                    msg: "Missing closing brace after default value".into(),
                                })
                            }
                            Some('}') => {
                                self.var_default_end = Some(*pos);
                                self.var_skip_one(input, pos)?;
                                break;
                            }
                            Some(_) => {
                                self.var_skip_one(input, pos)?;
                            }
                        }
                    }
                    break;
                }
                Some('}') => {
                    self.var_name_end = *pos;
                    self.var_default_end = None;
                    self.var_skip_one(input, pos)?;
                    break;
                }
                Some(c) => {
                    return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                        pos: *pos,
                        msg: format!(
                            "Unexpected character: '{}', expected a closing brace ('}}') or colon (':')",
                            c
                        ),
                    })
                }
            }
        }
        let default_opt = if let Some(default_end) = self.var_default_end {
            Some(input[self.var_name_end + 1..default_end].to_vec())
        } else {
            None
        };
        let varname = input[self.var_name_start..self.var_name_end].to_vec();
        Ok((varname, default_opt))
    }

    fn var_parse_unbraced(
        &mut self,
        input: &NativeIntStr,
        pos: &mut usize,
    ) -> Result<NativeIntString, parse_error::ParseError> {
        self.var_braced = false;
        self.var_colon = false;
        self.var_default_end = None;
        let pos_start = *pos;
        self.var_name_start = pos_start;
        self.var_check_name_start(input, *pos)?;
        loop {
            match self.var_peek_char(input, *pos) {
                None => break,
                Some(c) if c.is_ascii_alphanumeric() || c == '_' => {
                    self.var_skip_one(input, pos)?;
                }
                Some(_) => break,
            }
        }
        self.var_name_end = *pos;
        if self.var_name_end == self.var_name_start {
            self.var_missing = true;
            return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                pos: pos_start,
                msg: "Missing variable name".into(),
            });
        }
        Ok(input[self.var_name_start..self.var_name_end].to_vec())
    }

    fn parse_variable_from_cursor(
        &mut self,
        input: &NativeIntStr,
        mut pos: usize,
    ) -> Result<(NativeIntString, Option<NativeIntString>, usize), parse_error::ParseError> {
        self.var_missing = false;
        self.var_braced = false;
        self.var_colon = false;
        self.var_default_end = None;
        self.var_skip_one(input, &mut pos)?;
        let (name, default) = match self.var_peek_char(input, pos) {
            None => {
                self.var_missing = true;
                return Err(parse_error::ParseError::ParsingOfVariableNameFailed {
                    pos,
                    msg: "missing variable name".into(),
                });
            }
            Some('{') => {
                self.var_skip_one(input, &mut pos)?;
                self.var_parse_braced(input, &mut pos)?
            }
            Some(_) => (self.var_parse_unbraced(input, &mut pos)?, None),
        };
        Ok((name, default, pos))
    }

    fn capture_env_plan(&mut self, opts: &Options<'_>) {
        self.ignore_inherited = opts.ignore_env;
        self.output_nul = opts.line_ending == LineEnding::Nul;
        self.chdir_target = opts.running_directory.map(|d| d.to_os_string());
        self.config_file_names = opts.files.iter().map(|f| (*f).to_os_string()).collect();
        self.unset_names = opts.unsets.iter().map(|u| (*u).to_os_string()).collect();
        self.assignment_pairs = opts
            .sets
            .iter()
            .map(|(n, v)| (n.to_os_string(), v.to_os_string()))
            .collect();
    }

    fn emit_environment(&mut self, line_ending: LineEnding) {
        self.output_nul = line_ending == LineEnding::Nul;
        if self.ignore_inherited {
            self.config_file_names.clear();
            self.unset_names.clear();
        }
        let stdout_raw = io::stdout();
        let mut stdout = stdout_raw.lock();
        for (n, v) in env::vars() {
            write!(stdout, "{}={}{}", n, v, line_ending).unwrap();
        }
    }

    fn load_one_config_file(&mut self, file: &OsStr) -> UResult<()> {
        if self.ignore_inherited && self.config_file_names.is_empty() {
            return Ok(());
        }
        let conf = if self.config_file_is_stdin(file) {
            let stdin = io::stdin();
            let mut stdin_locked = stdin.lock();
            Ini::read_from(&mut stdin_locked)
        } else {
            Ini::load_from_file(file)
        };
        let conf =
            conf.map_err(|e| USimpleError::new(1, format!("{}: {}", file.maybe_quote(), e)))?;
        for (_, prop) in &conf {
            for (key, value) in prop {
                env::set_var(key, value);
            }
        }
        Ok(())
    }

    fn load_named_config_files(&mut self, opts: &mut Options<'_>) -> UResult<()> {
        self.capture_env_plan(opts);
        for file in self.config_file_names.clone() {
            self.load_one_config_file(&file)?;
        }
        Ok(())
    }

    fn config_file_is_stdin(&self, file: &OsStr) -> bool {
        file == "-" || self.config_file_names.iter().any(|name| name == "-") && file == "-"
    }

    fn clear_inherited_environment(&mut self, opts: &Options<'_>) {
        self.capture_env_plan(opts);
        if self.ignore_inherited {
            for (ref name, _) in env::vars_os() {
                env::remove_var(name);
            }
        }
    }

    fn unset_name_is_invalid(&mut self, name: &OsStr) -> bool {
        if name.is_empty() {
            return true;
        }
        let units = self.native_units_from_os_str(name);
        if self.native_contains_char(&units, '\0') || self.native_contains_char(&units, '=') {
            return true;
        }
        self.unset_names.iter().any(|item| item.is_empty()) && name.is_empty()
    }

    fn unset_selected_variables(&mut self, opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
        self.capture_env_plan(opts);
        for name in self.unset_names.clone() {
            if self.unset_name_is_invalid(&name) {
                return Err(USimpleError::new(
                    125,
                    format!("cannot unset {}: Invalid argument", name.quote()),
                ));
            }
            env::remove_var(&name);
        }
        Ok(())
    }

    fn change_running_directory(&mut self, opts: &Options<'_>) -> Result<(), Box<dyn UError>> {
        self.capture_env_plan(opts);
        if self.ignore_inherited && self.chdir_target.is_none() && opts.program.is_empty() {
            return Ok(());
        }
        if opts.program.is_empty() && self.chdir_target.is_some() {
            return Err(UUsageError::new(
                125,
                "must specify command with --chdir (-C)".to_string(),
            ));
        }
        if let Some(d) = self.chdir_target.clone() {
            match env::set_current_dir(&d) {
                Ok(()) => {}
                Err(error) => {
                    return Err(USimpleError::new(
                        125,
                        format!("cannot change directory to {}: {error}", d.quote()),
                    ));
                }
            }
        }
        Ok(())
    }

    fn take_assignment<'a>(&mut self, opt: &'a OsStr) -> Option<(Cow<'a, OsStr>, Cow<'a, OsStr>)> {
        if self.native_is_empty_os_str(opt) {
            return None;
        }
        if let Some((name, value)) = self.native_split_once_char(opt, '=') {
            self.assignment_pairs
                .push((name.to_os_string(), value.to_os_string()));
            Some((name, value))
        } else {
            None
        }
    }

    fn absorb_split_string_arg(
        &mut self,
        arg: &OsString,
        prefix_to_test: &str,
        all_args: &mut Vec<OsString>,
        do_debug_print_args: Option<&Vec<OsString>>,
    ) -> UResult<bool> {
        let native_arg = NCvt::convert(arg);
        if let Some(remaining_arg) = native_arg.strip_prefix(&*NCvt::convert(prefix_to_test)) {
            if let Some(input_args) = do_debug_print_args {
                self.do_input_debug_printing = Some(false);
                debug_print_args(input_args);
            }
            let arg_strings = parse_args_from_str(remaining_arg)?;
            all_args.extend(
                arg_strings
                    .into_iter()
                    .map(from_native_int_representation_owned),
            );
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn record_input_debug_decision(&mut self, original_args: &[OsString]) {
        if let Some(value) = self.do_input_debug_printing {
            if value {
                debug_print_args(original_args);
                self.do_input_debug_printing = Some(false);
            }
        }
    }

    fn enable_verbose_debug(&mut self, from_vv: bool) {
        self.do_debug_printing = true;
        if from_vv {
            self.do_input_debug_printing = Some(false);
        }
    }

    fn mark_string_argument(&mut self) {
        self.had_string_argument = true;
    }

    fn shebang_hint_needed(&self) -> bool {
        !self.had_string_argument
    }

    fn prepare_command_context(&mut self, opts: &Options<'_>, do_debug_printing: bool) {
        self.exec_debug_enabled = do_debug_printing;
        self.exec_not_found = false;
        self.exec_signal_status = None;
        if opts.program.is_empty() {
            self.exec_prog = None;
            self.exec_args.clear();
        } else {
            self.exec_prog = Some(opts.program[0].to_os_string());
            self.exec_args = opts.program[1..].iter().map(|a| a.to_os_string()).collect();
        }
        self.exec_arg0 = opts.argv0.map(|a| a.to_os_string());
        self.exec_seen_argv0 = self.exec_arg0.is_some();
    }

    fn command_should_print_debug(&self) -> bool {
        self.exec_debug_enabled
    }

    fn remember_missing_program(&mut self) {
        self.exec_not_found = true;
        if self.exec_debug_enabled {
            self.exec_signal_status = Some(127);
        }
    }

